@Composable fun ChecksScreen(vm:AppViewModel){val checks by vm.checks.collectAsState();val settings by vm.settings.collectAsState();val scope=rememberCoroutineScope();var entryDirection by remember{mutableStateOf<Int?>(null)};var showChooser by remember{mutableStateOf(false)};var filter by remember{mutableStateOf<Int?>(null)}
 if(entryDirection!=null){CheckEntryPage(vm,entryDirection!!,{entryDirection=null},{entryDirection=null});return}
 val shown=checks.filter{filter==null||it.direction==filter};Box(Modifier.fillMaxSize()){Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(start=16.dp,end=16.dp,top=12.dp,bottom=92.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("مدیریت چک‌ها",style=MaterialTheme.typography.headlineSmall);Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){FilterChip(filter==null,{filter=null},{Text("همه")});FilterChip(filter==CheckDirection.RECEIVED,{filter=CheckDirection.RECEIVED},{Text("دریافتی")});FilterChip(filter==CheckDirection.ISSUED,{filter=CheckDirection.ISSUED},{Text("صادرشده")})};if(shown.isEmpty())Text("هنوز چکی ثبت نشده است.",modifier=Modifier.padding(vertical=24.dp));shown.forEach{c->val received=c.direction==CheckDirection.RECEIVED;val accent=if(received)Color(0xFF20A565) else Color(0xFFE14B55);Card(colors=CardDefaults.cardColors(containerColor=accent.copy(alpha=.10f)),modifier=Modifier.fillMaxWidth().border(1.4.dp,accent,RoundedCornerShape(16.dp))){Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(c.counterparty,style=MaterialTheme.typography.titleMedium);Text(if(received)"چک دریافتی" else "چک صادرشده",color=accent,style=MaterialTheme.typography.labelLarge)};Text(Money.format(c.amountRial,settings.moneyUnit),style=MaterialTheme.typography.titleMedium,color=accent);Text("سررسید: ${PersianDate.fromMillis(c.dueAt).format()}");if(c.bankName.isNotBlank())Text("بانک: ${c.bankName}");if(c.sayadId.isNotBlank())Text("شناسه صیادی: ${c.sayadId}");if(c.serialNumber.isNotBlank())Text("سریال: ${c.serialNumber}");Text(when(c.status){CheckStatus.CLEARED->"وصول/پاس‌شده";CheckStatus.BOUNCED->"برگشت‌خورده";CheckStatus.CANCELLED->"لغوشده";else->"در انتظار"},color=accent);if(c.status==CheckStatus.PENDING)Row{TextButton({scope.launch{vm.repo.db.checkDao().update(c.copy(status=CheckStatus.CLEARED))}}){Text("وصول/پاس شد")};TextButton({scope.launch{vm.repo.db.checkDao().update(c.copy(status=CheckStatus.BOUNCED))}}){Text("برگشت خورد",color=MaterialTheme.colorScheme.error)}}}}}}
  FloatingActionButton({showChooser=true},Modifier.align(Alignment.BottomEnd).padding(20.dp),containerColor=MaterialTheme.colorScheme.primary){Icon(Icons.Filled.Add,"افزودن چک")}}
 if(showChooser)AlertDialog(onDismissRequest={showChooser=false},title={Text("نوع چک را انتخاب کنید")},text={Column(verticalArrangement=Arrangement.spacedBy(10.dp)){Button({showChooser=false;entryDirection=CheckDirection.RECEIVED},Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Color(0xFF1B8F52))){Text("ثبت چک دریافت‌شده")};Button({showChooser=false;entryDirection=CheckDirection.ISSUED},Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Color(0xFFD33B45))){Text("ثبت چک صادرشده")}}},confirmButton={})
